-- 1. 参数列表：
-- 1.1 key：秒杀优惠券ID
local voucherId = ARGV[1]
-- 1.2 key：用户ID
local userId = ARGV[2]
-- 1.3 key：订单id
local orderId = ARGV[3]

-- 2. 数据key
-- 2.1 库存key
local stockKey = 'seckill:stock:' .. voucherId
-- 2.2 订单key
local orderKey = 'seckill:order:' .. voucherId

-- 3. 脚本业务
-- 3.1 判断库存是否充足
local stock = redis.call('get', stockKey)
if (not stock or tonumber(stock) <= 0) then
    return 1
end
-- 3.2 判断用户是否重复下单
if (redis.call('sismember', orderKey, userId) == 1) then
    -- 用户重复下单
    return 2
end
-- 3.3 扣减库存
redis.call('incrby', stockKey, -1)  -- 减库存
redis.call('sadd', orderKey, userId) -- 添加id
-- Redis Stream acts as a local outbox. The relay acknowledges this event only
-- after Kafka confirms it, avoiding the reserve-success/send-lost gap.
redis.call('xadd', 'stream.orders', '*', 'userId', userId, 'voucherId', voucherId, 'id', orderId)
return 0
